import genanki,json,zipfile,sqlite3,tempfile,pathlib,re
D=json.loads("{\"cloze\":[[\"Neural pathways carrying sensory information toward the CNS are classified as {{c1::afferent}}.\",\"Organization\"],[\"Neural pathways carrying motor output away from the CNS are classified as {{c1::efferent}}.\",\"Organization\"],[\"The somatic motor pathway uses {{c1::one}} neuron between the CNS and skeletal muscle.\",\"Motor systems\"],[\"The autonomic motor pathway ordinarily uses a {{c1::two-neuron}} chain between the CNS and the effector.\",\"Motor systems\"],[\"Autonomic motor output targets smooth muscle, cardiac muscle, and {{c1::glands}}.\",\"Motor systems\"],[\"Sympathetic preganglionic neuronal cell bodies originate in the thoracolumbar spinal cord at {{c1::T1–L2/3}}.\",\"Sympathetic\"],[\"The spinal cord region containing sympathetic preganglionic neuronal cell bodies is the {{c1::intermediolateral cell column (IMLCC)}}.\",\"Sympathetic\"],[\"The communicating ramus that carries preganglionic sympathetic fibers into the sympathetic trunk is the {{c1::white ramus communicans}}.\",\"Sympathetic\"],[\"White rami communicantes are restricted to spinal levels {{c1::T1–L2/3}}.\",\"Sympathetic\"],[\"The communicating ramus that returns postganglionic sympathetic fibers to a spinal nerve is the {{c1::gray ramus communicans}}.\",\"Sympathetic\"],[\"The communicating rami present at every spinal level are the {{c1::gray rami communicantes}}.\",\"Sympathetic\"],[\"Sympathetic ganglia running alongside the vertebral column are called {{c1::paravertebral ganglia}}.\",\"Ganglia\"],[\"Sympathetic ganglia near the abdominal aorta, including the celiac and mesenteric ganglia, are {{c1::prevertebral ganglia}}.\",\"Ganglia\"],[\"Preganglionic sympathetic fibers destined for prevertebral ganglia travel through the trunk without {{c1::synapsing}}.\",\"Sympathetic\"],[\"The parasympathetic nervous system has a {{c1::craniosacral}} outflow.\",\"Parasympathetic\"],[\"The cranial nerves carrying parasympathetic outflow are {{c1::III, VII, IX, and X}}.\",\"Parasympathetic\"],[\"The sacral levels contributing parasympathetic outflow are {{c1::S2–S4}}.\",\"Parasympathetic\"],[\"Parasympathetic fibers traveling from S2–S4 toward pelvic plexuses pass through the {{c1::pelvic splanchnic nerves}}.\",\"Parasympathetic\"],[\"The enteric plexus located between intestinal muscle layers and involved in peristalsis is the {{c1::myenteric (Auerbach) plexus}}.\",\"Enteric\"],[\"The enteric plexus involved in secretion, water/electrolyte regulation, and local blood flow is the {{c1::submucosal (Meissner) plexus}}.\",\"Enteric\"],[\"Visceral pain afferents from structures above the pelvic pain line generally follow {{c1::sympathetic}} pathways.\",\"Visceral pain\"],[\"Visceral pain afferents from structures below the pelvic pain line generally follow {{c1::parasympathetic}} pathways.\",\"Visceral pain\"],[\"Visceral pain afferents below the pelvic pain line travel toward dorsal root ganglia at {{c1::S2–S4}}.\",\"Visceral pain\"],[\"Referred pain results from convergence of visceral and {{c1::somatic}} sensory inputs within the CNS.\",\"Visceral pain\"],[\"The four major named prevertebral sympathetic ganglion groups include celiac, superior mesenteric, inferior mesenteric, and {{c1::aorticorenal}}.\",\"Ganglia\"],[\"Autonomic ganglia situated near or within the wall of the target organ are classified as {{c1::intrinsic ganglia}}.\",\"Ganglia\"],[\"Sympathetic preganglionic fibers targeting the head and neck may {{c1::ascend}} within the sympathetic trunk before synapsing.\",\"Sympathetic routes\"],[\"Thoracic cardiopulmonary sympathetic pathways can use a {{c1::same-level synapse}} in the sympathetic trunk.\",\"Sympathetic routes\"],[\"Sympathetic fibers supplying lower regions of the trunk or limbs may {{c1::descend}} the sympathetic chain before synapsing.\",\"Sympathetic routes\"],[\"Following synapse in a prevertebral ganglion, the lecture traces sympathetic fibers toward abdominal visceral targets along {{c1::arteries}}.\",\"Sympathetic routes\"],[\"The four named parasympathetic ganglia in the head are ciliary, otic, pterygopalatine, and {{c1::submandibular}}.\",\"Parasympathetic\"],[\"The mnemonic used to remember the four parasympathetic head ganglia is {{c1::COPS}}.\",\"Parasympathetic\"],[\"Parasympathetic cranial nerve outflow associated with cardiac, thoracic, and intrinsic enteric ganglia is carried by {{c1::CN X (vagus)}}.\",\"Parasympathetic\"],[\"The cranial nerves identified in the lecture as having parasympathetic ganglia in the head are III, VII, and {{c1::IX}}.\",\"Parasympathetic\"],[\"The alternative name for the submucosal enteric plexus is the {{c1::Meissner plexus}}.\",\"Enteric\"],[\"The alternative name for the myenteric enteric plexus is the {{c1::Auerbach plexus}}.\",\"Enteric\"],[\"Preganglionic autonomic neurons release {{c1::acetylcholine}} at autonomic ganglia.\",\"Supplement\"],[\"Preganglionic autonomic acetylcholine acts at {{c1::nicotinic}} ganglionic receptors.\",\"Supplement\"],[\"Most sympathetic postganglionic terminals release {{c1::norepinephrine}}.\",\"Supplement\"],[\"A prominent exception to sympathetic norepinephrine signaling is the {{c1::cholinergic sweat-gland pathway}}.\",\"Supplement\"]],\"basic\":[[\"A student claims that somatic and autonomic motor pathways both require two peripheral neurons. Why is this incorrect?\",\"Somatic motor output reaches skeletal muscle through one motor neuron without a peripheral ganglionic synapse. Autonomic output ordinarily uses preganglionic and postganglionic neurons.\"],[\"A motor axon emerges from a thoracic spinal cord segment and must enter the sympathetic trunk. What route does it take?\",\"IMLCC → ventral root → spinal nerve → ventral ramus → white ramus communicans → sympathetic trunk.\"],[\"Why can gray rami communicantes be found at spinal levels that lack white rami?\",\"White rami carry preganglionic sympathetic fibers into the trunk only at T1–L2/3. Postganglionic fibers can reach other levels by traveling within the trunk before exiting through gray rami.\"],[\"A sympathetic preganglionic fiber enters the trunk but needs to reach the head or neck. What is the appropriate course?\",\"Ascend within the sympathetic trunk and synapse in a higher paravertebral ganglion.\"],[\"A sympathetic preganglionic fiber must reach an abdominal prevertebral ganglion. Does it synapse inside the sympathetic trunk?\",\"No. It traverses the trunk without synapsing and continues via an abdominopelvic splanchnic nerve to a prevertebral ganglion.\"],[\"Why is it incorrect to classify pelvic and abdominopelvic splanchnic nerves as the same autonomic pathway?\",\"Pelvic splanchnic nerves carry sacral parasympathetic outflow from S2–S4. Abdominopelvic splanchnic nerves carry sympathetic fibers that pass through the sympathetic trunk toward prevertebral ganglia.\"],[\"During pelvic surgery, a nerve pathway originating at S2–S4 is injured. Which division of autonomic outflow is implicated?\",\"Sacral parasympathetic outflow through the pelvic splanchnic nerves.\"],[\"Why is it incorrect to locate all parasympathetic ganglia beside the vertebral column?\",\"Parasympathetic ganglia are associated with the target region, often near or within organ walls, rather than forming the sympathetic paravertebral chain.\"],[\"An intestinal motility disturbance is attributed to injury of the plexus between muscle layers. Which plexus is affected, and what function is impaired?\",\"The myenteric (Auerbach) plexus; its primary function in the lecture is control of peristalsis.\"],[\"A lesion chiefly reduces intestinal secretion and regulation of local blood flow. Which enteric plexus is implicated?\",\"The submucosal (Meissner) plexus.\"],[\"Why might pain from a visceral organ be dull and difficult to localize?\",\"Visceral nociceptive signals are often poorly localized compared with somatic sensation, making the precise organ of origin difficult to identify.\"],[\"A clinician traces visceral pain originating above the pelvic pain line. Which pathway and spinal levels are expected?\",\"The pain afferents generally follow sympathetic pathways toward dorsal root ganglia at T1–L2.\"],[\"A clinician traces visceral pain originating below the pelvic pain line. Which pathway and spinal levels are expected?\",\"The pain afferents generally follow parasympathetic pathways toward dorsal root ganglia at S2–S4.\"],[\"A patient has anginal discomfort extending into the left upper limb despite no injury to the arm. What explains the referred pain?\",\"Visceral cardiac and somatic sensory inputs converge within the CNS, leading the brain to misattribute visceral pain to a body-wall region.\"],[\"Why is the statement 'afferent means somatic' incorrect?\",\"Afferent describes the direction of sensory information toward the CNS. Somatic describes the body-wall or limb distribution. The two terms classify different features.\"],[\"A sympathetic pathway enters the trunk, travels downward, and synapses in a lower paravertebral ganglion. Which of the four trunk routes does it represent?\",\"Descend and synapse. This supplies lower trunk and limb targets in the lecture's four-route classification.\"],[\"A preganglionic sympathetic axon enters the chain at a thoracic level, travels upward, and ultimately contributes to cervical sympathetic output. Why does it need to travel within the trunk?\",\"Sympathetic preganglionic neurons originate in the thoracolumbar cord, while sympathetic output must also reach the head and neck. Ascending within the trunk allows synapse at a higher paravertebral ganglion.\"],[\"A student argues that sympathetic output to the lower limb must arise directly from a lumbar segment at the same level as its target. What is the error?\",\"A sympathetic preganglionic axon can enter the chain from the thoracolumbar outflow and then descend before synapsing. The spinal origin and ganglionic synapse level need not match.\"],[\"Why should a nerve passing through the sympathetic trunk without synapsing not be classified as a postganglionic axon?\",\"Passing through the trunk does not itself create a synapse. It remains a preganglionic sympathetic axon until it synapses in a downstream ganglion, such as a prevertebral ganglion.\"],[\"A histologic specimen shows an autonomic ganglion immediately adjacent to the abdominal aorta. Which ganglion category is most consistent with this location?\",\"A prevertebral sympathetic ganglion, such as a celiac, mesenteric, or aorticorenal ganglion.\"],[\"Why is it incorrect to identify an intrinsic autonomic ganglion as a paravertebral ganglion?\",\"An intrinsic ganglion lies near or within a target organ wall; a paravertebral ganglion lies in the sympathetic chain beside the vertebral column.\"],[\"Why does the designation 'white ramus communicans' not imply that white rami occur at every spinal level?\",\"The name describes the communication pathway carrying preganglionic sympathetic fibers into the trunk. White rami are confined to the thoracolumbar outflow levels T1–L2/3.\"],[\"A student confuses the sacral parasympathetic outflow with the sympathetic fibers supplying abdominal viscera. What anatomic distinction resolves the error?\",\"Sacral parasympathetic outflow arises at S2–S4 and travels in pelvic splanchnic nerves. Sympathetic outflow originates at T1–L2/3 and can reach abdominal prevertebral ganglia through abdominopelvic splanchnic nerves.\"],[\"How can the 'COPS' mnemonic help distinguish parasympathetic ganglia in the head from the sympathetic chain?\",\"COPS identifies the four parasympathetic head ganglia: ciliary, otic, pterygopalatine, and submandibular. These are distinct from the paravertebral sympathetic chain.\"],[\"Why is CN X different from the other named cranial parasympathetic nerves in the lecture's ganglion-location summary?\",\"CN III, VII, and IX are associated with ganglia in the head, whereas CN X is associated with cardiac, thoracic, and enteric or intrinsic ganglia.\"],[\"A student claims the enteric nervous system has only one plexus controlling all intestinal functions. Why is this incorrect?\",\"The lecture distinguishes the myenteric (Auerbach) plexus, associated primarily with peristalsis, from the submucosal (Meissner) plexus, associated with secretion, water/electrolyte handling, and local blood flow.\"],[\"Why should a painful stimulus below the pelvic pain line not automatically be traced along sympathetic afferent pathways?\",\"The lecture states that visceral pain afferents below the pelvic pain line generally follow parasympathetic routes to S2–S4 dorsal root ganglia, rather than the thoracolumbar sympathetic routes used above the line.\"],[\"A student says that visceral pain referred to the jaw must indicate damage to jaw tissue. Why is this conclusion unwarranted?\",\"Visceral and somatic sensory inputs can converge centrally, causing the brain to localize visceral discomfort to a somatic territory. The lecture gives angina with possible jaw discomfort as an example.\"],[\"Why is it incorrect to assume that every sympathetic postganglionic neuron releases norepinephrine?\",\"The First Aid supplement identifies cholinergic sympathetic pathways to sweat glands as an important exception.\"],[\"A sympathetic pathway to the head is interrupted, resulting in a Horner syndrome presentation. How does this illustrate the anatomy reviewed in the lecture?\",\"The First Aid supplement uses Horner syndrome as an example of interrupted sympathetic head pathways, emphasizing the importance of the sympathetic route ascending toward the head.\"]]}")
assert len(D['cloze'])==40 and len(D['basic'])==30
cl=genanki.Model(2961306101,'MSK Lecture 6 Cloze',fields=[{'name':'Text'},{'name':'Extra'}],templates=[{'name':'Cloze','qfmt':'{{cloze:Text}}','afmt':'{{cloze:Text}}<hr id=answer>{{Extra}}'}],model_type=genanki.Model.CLOZE)
ba=genanki.Model(2961306102,'MSK Lecture 6 Basic',fields=[{'name':'Front'},{'name':'Back'}],templates=[{'name':'Basic','qfmt':'{{Front}}','afmt':'{{FrontSide}}<hr id=answer>{{Back}}'}])
deck=genanki.Deck(2961306199,'MSK · Week 13 · Lecture 6')
for t,tag in D['cloze']:
 assert t.count('{{c1::')==1 and re.search(r'{{c[2-9]::',t) is None and t.count('}}')==1
 deck.add_note(genanki.Note(model=cl,fields=[t,''],tags=[tag.replace(' ','_')]))
for q,a in D['basic']:
 assert q and a
 deck.add_note(genanki.Note(model=ba,fields=[q,a]))
out=pathlib.Path(__file__).with_name('MSK_Week13_Lecture6_Text_Only.apkg')
genanki.Package(deck).write_to_file(str(out))
with zipfile.ZipFile(out) as z:
 assert z.testzip() is None
 with tempfile.TemporaryDirectory() as d:
  p=pathlib.Path(d)/'collection.anki2';p.write_bytes(z.read('collection.anki2'))
  db=sqlite3.connect(p)
  assert db.execute('pragma integrity_check').fetchone()[0]=='ok'
  assert db.execute('select count(*) from notes').fetchone()[0]==70
  assert db.execute('select count(*) from cards').fetchone()[0]==70
print('PASS: 40 Cloze + 30 Basic = 70 cards',out,out.stat().st_size)

